if mibBuilder.loadTexts: expSfpType.setDescription('This variable indicates the type of the SFP. It is a bitmap represented\n         as a sum, therefore, it can represent multiple types (combination\n         of types) simultaneously. The various bit positions are:\n             bit 0 (1):  1000BASE-SX\n             bit 1 (2):  1000BASE-LX\n             bit 2 (4):  1000BASE-CX\n             bit 3 (8):  1000BASE-T\n             bit 4 (16): 100BASE-LX/LX10\n             bit 5 (32): 100BASE-FX\n             bit 6 (64): BASE-BX10\n             bit 7 (128): BASE-PX\n             bit 16 (65536):  2500BASE-SX\n             bit 17 (131072): 2500BASE-LX\n             bit 18 (262144): 2500BASE-BX             \n        If the expSfpType is unknown or not specified, expSfpType = 0.\n        ALCATEL NOTE: \n            ACCESS: RO\n            USAGE: NA\n            PERSIST: NO \n            INSRVMOD: NA\n            RANGE: NA\n            DEFVALUE: 0\n            UNITS: NA \n            SPARSE: NO\n            DESCR: NA\n        ')
hostSfpLogSlotId = MibTableColumn((1, 3, 6, 1, 4, 1, 637, 61, 1, 56, 4, 1, 7), EqptSlotIndex()).setMaxAccess("readonly")
if mibBuilder.loadTexts: hostSfpLogSlotId.setStatus('mandatory')
if mibBuilder.loadTexts: hostSfpLogSlotId.setDescription('This is the LogSlotId of the host LT which the expansion\n         shelf SFP is cabled to. If an expansion shelf SFP is not cabled to any\n         host shelf SFP, the value of the corresponding hostSfpLogSlotId\n         is set to 0.\n        ALCATEL NOTE:\n            ACCESS: RO\n            USAGE: NA\n            PERSIST: NO\n            INSRVMOD: NA\n            RANGE: see above\n            DEFVALUE: 0\n            UNITS: NA\n            SPARSE: NO\n            DESCR: NA\n        ')
sfpDiagTable = MibTable((1, 3, 6, 1, 4, 1, 637, 61, 1, 56, 5), ).setMaxAccess("notaccessible")
if mibBuilder.loadTexts: sfpDiagTable.setStatus('mandatory')
if mibBuilder.loadTexts: sfpDiagTable.setDescription("The primary purpose of this read-only table:  allow the SNMP \n         manager to read real-time diagnostic measurements (e.g. the \n         SFP's received optical power level) from the A2 bank of a \n         manager-specified SFP.  The A2 bank and content are defined in \n         the SFF-8472 standard (available at ftp.seagate.com).  \n\n         The table is indexed to allow support for any SFP cage in \n         the system.  \n\n         In a particular release, SFP diagnostics support for a \n         particular assembly may or may not be provided, and support for \n         all the cages on a supported assembly may or may not be \n         provided.  If an assembly has any supported SFP cages, a row will be \n         present in this table for each of its SFP cages.  \n\n         A row is present whether or not the SFP cage contains an SFP,\n         and whether or not the SFP supports diagnostics.  If the SFP \n         cage contains an SFP, some status information (e.g. LOS and \n         TxFault status) is available in the row.  An enumerated object \n         (sfpDiagAvailable) is used to indicate the condition/error \n         (or no error) encountered when attempting to read the \n         diagnostics information for the specified cage (e.g. cage \n         empty, or A2 checksum failed). \n\n         Details are documented with the individual objects.\n\n         The following table size field is set to 'not applicable', \n         since it does not make sense for the SNMP manager to cache the \n         values in this table.  The values will be different each time \n         they are read from agent.\n\n         ALCATEL NOTE:\n            TABLESIZE: NA\n            DESCR:  NA \n        ")
sfpDiagEntry = MibTableRow((1, 3, 6, 1, 4, 1, 637, 61, 1, 56, 5, 1), ).setMaxAccess("notaccessible").setIndexNames((0, "SFP-MIB", "sfpDiagLogicalSlot"), (0, "SFP-MIB", "sfpDiagSfpFaceplateNumber"))
if mibBuilder.loadTexts: sfpDiagEntry.setStatus('mandatory')
if mibBuilder.loadTexts: sfpDiagEntry.setDescription('The index for the sfpDiagTable identifies an SFP cage \n         using two fields:  the logicalSlotId of the card associated \n         with the SFP cage (normally the card with the cages on its \n         faceplate), and the SFP cage number.')
sfpDiagLogicalSlot = MibTableColumn((1, 3, 6, 1, 4, 1, 637, 61, 1, 56, 5, 1, 1), Integer32()).setMaxAccess("readonly")
if mibBuilder.loadTexts: sfpDiagLogicalSlot.setStatus('mandatory')
if mibBuilder.loadTexts: sfpDiagLogicalSlot.setDescription('This is the first index of the sfpDiagTable.  \n\n         Normally, this object contains the Logical Slot ID (as defined in\n         the Equipment MIB) of the card which has the SFP cage of interest\n         on its faceplate.\n         If that card does not have a Logical Slot ID, the Logical Slot ID\n         of a related card is used.\n         \n        ALCATEL NOTE:\n            ACCESS: RO\n            USAGE: NA\n            PERSIST: NO \n            INSRVMOD: NO\n            RANGE: 1..65535\n            DEFVALUE: NA\n            UNITS: NA \n            SPARSE: NO\n            DESCR: NA\n        ')
sfpDiagSfpFaceplateNumber = MibTableColumn((1, 3, 6, 1, 4, 1, 637, 61, 1, 56, 5, 1, 2), Integer32()).setMaxAccess("readonly")
if mibBuilder.loadTexts: sfpDiagSfpFaceplateNumber.setStatus('mandatory')
if mibBuilder.loadTexts: sfpDiagSfpFaceplateNumber.setDescription('This is the second index of the sfpDiagTable. \n         It is the number of the SFP cage, as shown on the card \n         faceplate.  If the faceplate cage number is zero, \n         sfpDiagSfpFaceplateNumber=0 is used (i.e. zero is not a\n         special case).\n         For an SFP cage, it is the faceplate number of the SFP cage \n         (e.g. 1).\n         For an SFP+/XFP cage, it is 256 + the faceplate number \n         of the XFP cage.  For example, if the SFP+/XFP cage has \n         faceplate label X1, sfpInvFaceplateNumber = 257.\n         For an QSFP cage, it is 512 + the faceplate number \n         of the QSFP cage.  For example, if the QSFP cage has \n         faceplate label Q1, sfpInvFaceplateNumber = 513.\n         For a CFP4 cage, it is 768 + the faceplate number \n         of the CFP4 cage.  For example, if the CFP4 cage has \n         faceplate label C1, sfpInvFaceplateNumber = 769.\n\n        ALCATEL NOTE:\n            ACCESS: RO\n            USAGE: NA\n            PERSIST: NO \n            INSRVMOD: NO\n            RANGE: 0..769\n            DEFVALUE: NA\n            UNITS: NA \n            SPARSE: NO\n            DESCR: NA\n        ')
sfpDiagAvailable = MibTableColumn((1, 3, 6, 1, 4, 1, 637, 61, 1, 56, 5, 1, 3), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2, 3, 4, 5, 6, 7, 8, 9))).clone(namedValues=NamedValues(("noError", 1), ("cageDoesNotSupportDiag", 2), ("cageEmpty", 3), ("cageDoesNotSupportA2", 4), ("a0ReadFailed", 5), ("a0ChecksumFailed", 6), ("sfpDoesNotSupportA2", 7), ("a2ReadFailed", 8), ("a2ChecksumFailed", 9)))).setMaxAccess("readonly")
if mibBuilder.loadTexts: sfpDiagAvailable.setStatus('mandatory')
if mibBuilder.loadTexts: sfpDiagAvailable.setDescription("A column in the sfpDiagTable, with the following code points.\n\n         noError - valid values for all objects in this row (e.g. \n           sfpDiagRxPower) were obtained from the SFP in the specified \n           cage.\n         cageDoesNotSupportDiag - the specified cage does not support \n           reading LOS, TxFault, or A2 measurements.  All subsequent values in the \n           row have notAvailable or 'Not Available' values. \n         cageEmpty - the specified SFP cage does not contain an SFP. \n           All subsequent values in the row have notAvailable or \n           'Not Available' values. \n         cageDoesNotSupportA2 - the specified SFP cage does not support \n           access to the SFP A2 bank (e.g. because of limitations in \n           FPGA support on the host card).  sfpDiagLOS and \n           sfpDiagTxFault have valid values (since they are implemented \n           using external signals, not SFP EEPROM values).\n         a0ReadFailed - the attempt to read the A0 bank of the \n           specified SFP failed.  A0 is read to determine if A2 is \n           supported, so no attempt was made to read the A2 \n           information.  sfpDiagLOS and sfpDiagTxFault have valid \n           values (since they are implemented using external signals, \n           not SFP EEPROM values).\n         a0ChecksumFailed - the A0 bank of the SFP EEPROM is \n           corrupted.  sfpDiagLOS and sfpDiagTxFault have valid values \n           (since they are implemented using external signals, not SFP \n           EEPROM values).\n         sfpDoesNotSupportA2 - the A0 bank of the SFP EEPROM indicates\n           A2 is not supported.  sfpDiagLOS and sfpDiagTxFault have \n           valid values (since they are implemented using external \n           signals, not SFP EEPROM values). \n         a2ReadFailed - the attempt to read the A2 bank of the \n           specified SFP failed.  sfpDiagLOS and sfpDiagTxFault have \n           valid values (since they are implemented using external \n           signals, not SFP EEPROM values).\n         a2ChecksumFailed - the A2 bank of the SFP EEPROM is \n           corrupted.  sfpDiagLOS and sfpDiagTxFault have valid values \n           (since they are implemented using external signals, not SFP \n           EEPROM values).\n  \n\n         ALCATEL NOTE:\n           ACCESS: RO\n           USAGE: NA\n           PERSIST: NO \n           INSRVMOD: NO\n           RANGE: NA\n           DEFVALUE: NA\n           UNITS: NA \n           SPARSE: NO\n           DESCR: NA\n       ")
sfpDiagLOS = MibTableColumn((1, 3, 6, 1, 4, 1, 637, 61, 1, 56, 5, 1, 4), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2, 3))).clone(namedValues=NamedValues(("los", 1), ("noLos", 2), ("notAvailable", 3)))).setMaxAccess("readonly")
if mibBuilder.loadTexts: sfpDiagLOS.setStatus('mandatory')
if mibBuilder.loadTexts: sfpDiagLOS.setDescription('A column in the sfpDiagTable, with the following code \n         points.\n\n         los - the SFP in the specified SFP cage has detected Loss of \n           Signal (on its receiver).\n         noLos - the SFP in the specified SFP cage has detected a\n           received signal with a suitable power level.  \n         notAvailable - the status of the received signal for the \n           specified SFP cage cannot be determined (e.g. because the \n           cage is empty - see sfpDiagAvailable).\n\n         ALCATEL NOTE:\n           ACCESS: RO\n           USAGE: NA\n           PERSIST: NO \n           INSRVMOD: NO\n           RANGE: NA\n           DEFVALUE: NA\n           UNITS: NA \n           SPARSE: NO\n           DESCR: NA\n        ')
sfpDiagTxFault = MibTableColumn((1, 3, 6, 1, 4, 1, 637, 61, 1, 56, 5, 1, 5), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2, 3, 4))).clone(namedValues=NamedValues(("txFault", 1), ("noTxFault", 2), ("notApplicable", 3), ("notAvailable", 4)))).setMaxAccess("readonly")
if mibBuilder.loadTexts: sfpDiagTxFault.setStatus('mandatory')
if mibBuilder.loadTexts: sfpDiagTxFault.setDescription('A column in the sfpDiagTable, with the following code \n         points.\n\n         txFault - the SFP in the specified SFP cage has detected a \n           TxFault error (as defined in SFF-8472).\n         noTxFault - the SFP in the specified SFP cage has not detected \n           a TxFault error.\n         notApplicable - the SFP is electrical, so TxFault is not \n           applicable (the detection technology is optical).\n         notAvailable - the TxFault status of the specified SFP cage \n           cannot be determined (e.g. because the cage is empty - see \n           sfpDiagAvailable).\n\n         ALCATEL NOTE:\n           ACCESS: RO\n           USAGE: NA\n           PERSIST: NO \n           INSRVMOD: NO\n           RANGE: NA\n           DEFVALUE: NA\n           UNITS: NA \n           SPARSE: NO\n           DESCR: NA\n        ')
sfpDiagTxPower = MibTableColumn((1, 3, 6, 1, 4, 1, 637, 61, 1, 56, 5, 1, 6), DisplayString()).setMaxAccess("readonly")
if mibBuilder.loadTexts: sfpDiagTxPower.setStatus('mandatory')
if mibBuilder.loadTexts: sfpDiagTxPower.setDescription("A column in the sfpDiagTable, containing the freshly-measured \n         transmit power of the specified SFP, encoded into a string.\n\n         Five types of values are supported.  In the following text, \n         strings are enclosed in single quotes (a double quote marks the \n         end of the DESCRIPTION field).  \n\n         1.  '-40.00 dBm' to '8.16 dBm', in 0.01 dBm increments.  Note \n              that ' dBm' is included in the string.\n\n         2.  'No Power'.  This is a special case because an SFP reading \n             of 0.00 mW cannot be converted to dBm (since log10(0.00) is  \n             undefined). \n\n         3.  'Not Applicable'.  This is used for an electrical SFP.  The \n             technology for measuring transmitted power is optical.\n\n         4.  'Not Available'.  The measurement could not be obtained  \n             (e.g. the specified SFP cage is empty).\n\n         5.  'Invalid'. The transmitted power, in mW, is negative (for example,\n             due to incorrect external calibration constants in the SFP).  A\n             negative mW value is not valid in this context, and cannot be\n             converted to dBm.\n\n         ALCATEL NOTE:\n             ACCESS: RO\n             USAGE: NA\n             PERSIST: NO \n             INSRVMOD: NO\n             RANGE: NA\n             DEFVALUE: NA\n             UNITS: NA \n             SPARSE: NO\n             DESCR: NA\n        ")
sfpDiagRxPower = MibTableColumn((1, 3, 6, 1, 4, 1, 637, 61, 1, 56, 5, 1, 7), DisplayString()).setMaxAccess("readonly")
if mibBuilder.loadTexts: sfpDiagRxPower.setStatus('mandatory')
if mibBuilder.loadTexts: sfpDiagRxPower.setDescription("A column in the sfpDiagTable, containing the freshly-measured \n         received power of the specified SFP, encoded into a string.\n\n         Five types of values are supported.  In the following text, \n         strings are enclosed in single quotes (a double quote marks the \n         end of the DESCRIPTION field).  \n\n         1.  '-40.00 dBm' to '8.16 dBm', in 0.01 dBm increments.  Note \n             that ' dBm' is included in the string.\n\n         2.  'No Power'.  This is a special case because an SFP reading \n             of 0.00 mW cannot be converted to dBm (since log10(0.00) is  \n             undefined).\n\n         3.  'Not Applicable'.  This is used for an electrical SFP.  The \n             technology for measuring received power is optical.\n\n         4.  'Not Available'.  The measurement could not be obtained  \n             (e.g. the specified SFP cage is empty).\n\n         5.  'Invalid'. The received power, in mW, is negative (for example,\n             due to incorrect external calibration constants in the SFP).  A\n             negative mW value is not valid in this context, and cannot be\n             converted to dBm.   \n      \n         ALCATEL NOTE:\n             ACCESS: RO\n             USAGE: NA\n             PERSIST: NO \n             INSRVMOD: NO\n             RANGE: NA\n             DEFVALUE: NA\n             UNITS: NA \n             SPARSE: NO\n             DESCR: NA\n       ")
sfpDiagTxBiasCurrent = MibTableColumn((1, 3, 6, 1, 4, 1, 637, 61, 1, 56, 5, 1, 8), DisplayString()).setMaxAccess("readonly")
if mibBuilder.loadTexts: sfpDiagTxBiasCurrent.setStatus('mandatory')
if mibBuilder.loadTexts: sfpDiagTxBiasCurrent.setDescription("A column in the sfpDiagTable, containing the freshly-measured \n         transmit bias current of the specified SFP, encoded into a \n         string.\n\n         Four types of values are supported.  In the following text, \n         strings are enclosed in single quotes (a double quote marks the \n         end of the DESCRIPTION field).  \n\n         1.  '0.00 mA' to '131.10 mA', in 0.01 mA increments.  Note that \n             ' mA' is included in the string.\n\n         2.  'Not Applicable'.  This is used for an electrical SFP.  The \n             technology for measuring transmit bias current is optical.\n\n         3.  'Not Available'.  The measurement could not be obtained  \n             (e.g. the specified SFP cage is empty).\n\n         4.  'Invalid'. The bias current, in mA, is negative (for example,\n             due to incorrect external calibration constants in the SFP).  A\n             negative mA value is not valid in this context.\n\n         ALCATEL NOTE:\n             ACCESS: RO\n             USAGE: NA\n             PERSIST: NO \n             INSRVMOD: NO \n             RANGE: NA\n             DEFVALUE: NA\n             UNITS: NA \n             SPARSE: NO\n             DESCR: NA\n        ")
sfpDiagSupplyVoltage = MibTableColumn((1, 3, 6, 1, 4, 1, 637, 61, 1, 56, 5, 1, 9), DisplayString()).setMaxAccess("readonly")
if mibBuilder.loadTexts: sfpDiagSupplyVoltage.setStatus('mandatory')
if mibBuilder.loadTexts: sfpDiagSupplyVoltage.setDescription("A column in the sfpDiagTable, containing the freshly-measured \n         supply voltage of the specified SFP, encoded into a string.\n\n         Three types of values are supported.  In the following text, \n         strings are enclosed in single quotes (a double quote marks the \n         end of the DESCRIPTION field).  \n\n         1.  '0.00 VDC' to '6.55 VDC', in 0.01 VDC increments.  Note that \n             ' VDC' is included in the string.\n\n         2.  'Not Available'.  The measurement could not be obtained  \n             (e.g. the specified SFP cage is empty).\n\n         3.  'Invalid'. The supply voltage, in VDC, is negative (for example,\n             due to incorrect external calibration constants in the SFP).  A\n             negative VDC value is not valid in this context.\n\n         The supply voltage can be retrieved from an electrical SFP, so \n         there is no need for a 'Not Applicable' string.\n\n         ALCATEL NOTE:\n             ACCESS: RO\n             USAGE: NA\n             PERSIST: NO \n             INSRVMOD: NO\n             RANGE: NA\n             DEFVALUE: NA\n             UNITS: NA \n             SPARSE: NO\n             DESCR: NA\n        ")
sfpDiagTemperature = MibTableColumn((1, 3, 6, 1, 4, 1, 637, 61, 1, 56, 5, 1, 10), DisplayString()).setMaxAccess("readonly")
if mibBuilder.loadTexts: sfpDiagTemperature.setStatus('mandatory')
if mibBuilder.loadTexts: sfpDiagTemperature.setDescription("A column in the sfpDiagTable, containing the freshly-measured \n         temperature of the specified SFP, encoded into a string.\n\n         Two types of values are supported.  In the following text, \n         strings are enclosed in single quotes (a double quote marks the \n         end of the DESCRIPTION field).  \n\n         1.  '-128.00 degrees Celsius' to '128.00 degrees Celsius', \n             in 0.01 degrees Celsius increments.  \n             Note that ' degrees Celsius' is included in the string.\n\n         2.  'Not Available'.  The measurement could not be obtained  \n             (e.g. the specified SFP cage is empty).\n\n         The temperature can be retrieved from an electrical SFP, so \n         there is no need for a 'Not Applicable' string.\n\n         ALCATEL NOTE:\n             ACCESS: RO\n             USAGE: NA\n             PERSIST: NO \n             INSRVMOD: NO\n             RANGE: NA\n             DEFVALUE: NA\n             UNITS: NA \n             SPARSE: NO\n             DESCR: NA\n        ")
sfpDiagTCAStatusTemperature = MibTableColumn((1, 3, 6, 1, 4, 1, 637, 61, 1, 56, 5, 1, 11), SfpDiagTCAStatus()).setMaxAccess("readonly")
if mibBuilder.loadTexts: sfpDiagTCAStatusTemperature.setStatus('mandatory')
if mibBuilder.loadTexts: sfpDiagTCAStatusTemperature.setDescription('A column in the sfpDiagTable, containing the freshly-measured temperature \n        alarm/warning threshold crossing status of the specified SFP/SFP+/XFP/CFP4.\n        \n         ALCATEL NOTE:\n             ACCESS: RO\n             USAGE: NA\n             PERSIST: NO \n             INSRVMOD: NO\n             RANGE: NA\n             DEFVALUE: NA\n             UNITS: NA \n             SPARSE: NO\n             DESCR: NA\n        ')
sfpDiagTCAStatusVoltage = MibTableColumn((1, 3, 6, 1, 4, 1, 637, 61, 1, 56, 5, 1, 12), SfpDiagTCAStatus()).setMaxAccess("readonly")
if mibBuilder.loadTexts: sfpDiagTCAStatusVoltage.setStatus('mandatory')
if mibBuilder.loadTexts: sfpDiagTCAStatusVoltage.setDescription('A column in the sfpDiagTable, containing the freshly-measured voltage \n         alarm/warning threshold crossing status of the specified SFP/SFP+/XFP/CFP4.\n         For XFP, this parameter will display as NotAvailable in case it is not \n         supported as one of the Auxillary measured value by XFP.\n\n         ALCATEL NOTE:\n             ACCESS: RO\n             USAGE: NA\n             PERSIST: NO \n             INSRVMOD: NO\n             RANGE: NA\n             DEFVALUE: NA\n             UNITS: NA \n             SPARSE: NO\n             DESCR: NA\n        ')
sfpDiagTCAStatusBiasCurrent = MibTableColumn((1, 3, 6, 1, 4, 1, 637, 61, 1, 56, 5, 1, 13), SfpDiagTCAStatus()).setMaxAccess("readonly")
if mibBuilder.loadTexts: sfpDiagTCAStatusBiasCurrent.setStatus('mandatory')
if mibBuilder.loadTexts: sfpDiagTCAStatusBiasCurrent.setDescription('A column in the sfpDiagTable, containing the freshly-measured bias current \n        alarm/warning threshold crossing status of the specified SFP/SFP+/XFP/CFP4.\n        \n         ALCATEL NOTE:\n             ACCESS: RO\n             USAGE: NA\n             PERSIST: NO \n             INSRVMOD: NO\n             RANGE: NA\n             DEFVALUE: NA\n             UNITS: NA \n             SPARSE: NO\n             DESCR: NA\n        ')
sfpDiagTCAStatusTxPower = MibTableColumn((1, 3, 6, 1, 4, 1, 637, 61, 1, 56, 5, 1, 14), SfpDiagTCAStatus()).setMaxAccess("readonly")
if mibBuilder.loadTexts: sfpDiagTCAStatusTxPower.setStatus('mandatory')
if mibBuilder.loadTexts: sfpDiagTCAStatusTxPower.setDescription('A column in the sfpDiagTable, containing the freshly-measured received \n        power alarm/warning threshold crossing status of the specified SFP/SFP+/XFP/CFP4.\n\n         ALCATEL NOTE:\n             ACCESS: RO\n             USAGE: NA\n             PERSIST: NO \n             INSRVMOD: NO\n             RANGE: NA\n             DEFVALUE: NA\n             UNITS: NA \n             SPARSE: NO\n             DESCR: NA\n        ')
sfpDiagTCAStatusRxPower = MibTableColumn((1, 3, 6, 1, 4, 1, 637, 61, 1, 56, 5, 1, 15), SfpDiagTCAStatus()).setMaxAccess("readonly")
if mibBuilder.loadTexts: sfpDiagTCAStatusRxPower.setStatus('mandatory')
if mibBuilder.loadTexts: sfpDiagTCAStatusRxPower.setDescription('A column in the sfpDiagTable, containing the freshly-measured transmit \n        power alarm/warning threshold crossing status of the specified SFP/SFP+/XFP/CFP4.\n        \n         ALCATEL NOTE:\n             ACCESS: RO\n             USAGE: NA\n             PERSIST: NO \n             INSRVMOD: NO\n             RANGE: NA\n             DEFVALUE: NA\n             UNITS: NA \n             SPARSE: NO\n             DESCR: NA\n        ')
sfpDiagRSSIProfileId = MibTableColumn((1, 3, 6, 1, 4, 1, 637, 61, 1, 56, 5, 1, 16), Integer32()).setMaxAccess("readwrite")
