if mibBuilder.loadTexts: sfpDiagRSSIState.setStatus('mandatory')
if mibBuilder.loadTexts: sfpDiagRSSIState.setDescription('Enable(1) and Disable(2) to RSSI function on port level. \n\nALCATEL NOTE:\n\t\t ACCESS: NA        usage: OPT\n\t\t persistent: YES   INSRVMOD:YES\n                             RANGE:1,2          DEFVALUE: 2 \n                             UNITS: NA         SPARSE: NA  ')
sfpDiagRSSIRxPowerAlmLow = MibTableColumn((1, 3, 6, 1, 4, 1, 637, 61, 1, 56, 5, 1, 18), DisplayString()).setMaxAccess("readonly")
if mibBuilder.loadTexts: sfpDiagRSSIRxPowerAlmLow.setStatus('mandatory')
if mibBuilder.loadTexts: sfpDiagRSSIRxPowerAlmLow.setDescription("this object indicates the threshold for alarm OLTRXPWLO. if RX power is less than this value,then alarm OLTRXPWLO will be reported.\n                For CFP4, there is no module level 'RxPower' monitor,this is the threshold for network lane. \n                For ONT Profile, 0.5dBm means using ont internal policy.\n\t        'Not Available' is shown when the measurement could not be obtained,If the specified SFP cage is empty or if RSSI is not enabled and no profile assigned threshold values.\n                'Not Supported' is shown when the matching profile is not found.\n\n                ALCATEL NOTE:\n                 ACCESS:     RO       USAGE:    NA\n                 PERSIST:    NO       INSRVMOD: NA\n                 RANGE:      NA       DEFVALUE: NA\n                 UNITS:      NA       SPARSE:   NA\n                 DESCR:      NA ")
