sfpInventoryEntry = MibTableRow((1, 3, 6, 1, 4, 1, 637, 61, 1, 56, 6, 1), ).setMaxAccess("notaccessible").setIndexNames((0, "SFP-MIB", "sfpInvLogicalSlot"), (0, "SFP-MIB", "sfpInvFaceplateNumber"))
